import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import { Canvas, Circle, Points, RoundedRect } from "@shopify/react-native-skia";
import { useDerivedValue, useFrameCallback, useSharedValue, type SharedValue } from "react-native-reanimated";
import {
  PENDULUM_DEFAULTS,
  bobPositions,
  createPendulum,
  restPendulum,
  stepPendulumFixed,
  trailIndex,
  type PendulumConfig,
  type PendulumPointer,
  type PendulumState,
} from "./pendulumMath";
import {
  BOB_RADIUS,
  ELBOW_TRAIL,
  PENDULUM_ARM,
  PENDULUM_BACKGROUND,
  PENDULUM_BOB,
  PENDULUM_H,
  PENDULUM_ORIGIN_X,
  PENDULUM_ORIGIN_Y,
  PENDULUM_PX_PER_M,
  PENDULUM_W,
  TIP_TRAIL,
  TRAIL_BUCKETS,
  TRAIL_LAYERS,
  trailStyle,
  type TrailSpec,
} from "./pendulumDesign";

export type ChaosPendulumProps = {
  slowMotion?: boolean;
  reducedMotion?: boolean;
  onFeedback?: (event: "grab" | "release") => void;
  label?: string;
  style?: ViewStyle;
};

function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

type TrailProps = {
  sim: SharedValue<PendulumState>;
  frame: SharedValue<number>;
  tip: boolean;
  bucket: number;
  spec: TrailSpec;
  layers: number;
};

function TrailBucket({ sim, frame, tip, bucket, spec, layers }: TrailProps) {
  const length = PENDULUM_DEFAULTS.trailLength;
  const per = length / TRAIL_BUCKETS;
  const style = trailStyle(spec, bucket, TRAIL_BUCKETS);
  const points = useDerivedValue(() => {
    frame.value;
    const s = sim.value;
    const buf = tip ? s.trail2 : s.trail1;
    const out: { x: number; y: number }[] = [];
    for (let k = bucket * per; k <= (bucket + 1) * per; k++) {
      const i = trailIndex(s, length, k);
      if (i < 0) break;
      out.push({ x: buf[i * 2], y: buf[i * 2 + 1] });
    }
    if (out.length < 2) return [{ x: -20, y: -20 }, { x: -20, y: -20 }];
    return out;
  });
  const shown = TRAIL_LAYERS.slice(TRAIL_LAYERS.length - layers);
  return (
    <>
      {shown.map((layer) => (
        <Points
          key={layer.width}
          points={points}
          mode="polygon"
          color={style.color}
          opacity={Math.min(1, layer.alpha * style.alpha)}
          style="stroke"
          strokeWidth={layer.width}
          strokeCap="butt"
          strokeJoin="round"
        />
      ))}
    </>
  );
}

export function ChaosPendulum({
  slowMotion = false,
  reducedMotion,
  onFeedback,
  label = "Chaos pendulum",
  style,
}: ChaosPendulumProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const cfg: PendulumConfig = useMemo(
    () => ({ originX: PENDULUM_ORIGIN_X, originY: PENDULUM_ORIGIN_Y, pixelsPerMeter: PENDULUM_PX_PER_M }),
    [],
  );
  const opts = useMemo(() => PENDULUM_DEFAULTS, []);
  const sim = useSharedValue<PendulumState>(createPendulum(opts));
  const frame = useSharedValue(0);
  const pointer = useSharedValue<PendulumPointer>({ x: 0, y: 0, active: 0 });
  const slowM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const latest = useRef({ reduce, onFeedback });
  latest.current = { reduce, onFeedback };

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => {
    slowM.value = slowMotion;
  }, [slowMotion, slowM]);
  useEffect(() => {
    reduceM.value = reduce;
    const fresh = createPendulum(opts);
    if (reduce) restPendulum(fresh, 0.55, 0.85);
    sim.value = fresh;
    frame.value = frame.value + 1;
  }, [reduce, reduceM, sim, frame, opts]);

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          pointer.value = { x: evt.nativeEvent.locationX, y: evt.nativeEvent.locationY, active: 1 };
          latest.current.onFeedback?.("grab");
        },
        onPanResponderMove: (evt) => {
          pointer.value = { x: evt.nativeEvent.locationX, y: evt.nativeEvent.locationY, active: 1 };
        },
        onPanResponderRelease: () => {
          pointer.value = { x: 0, y: 0, active: 0 };
          latest.current.onFeedback?.("release");
        },
        onPanResponderTerminate: () => {
          pointer.value = { x: 0, y: 0, active: 0 };
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [pointer],
  );

  useFrameCallback((info) => {
    if (reduceM.value) return;
    const s = sim.value;
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    stepPendulumFixed(s, cfg, dt * (slowM.value ? 0.25 : 1), pointer.value, opts);
    frame.value = frame.value + 1;
  });

  const bobs = useDerivedValue(() => {
    frame.value;
    const out = [0, 0, 0, 0];
    bobPositions(sim.value, cfg, opts, out);
    return out;
  });
  const arm = useDerivedValue(() => [
    { x: cfg.originX, y: cfg.originY },
    { x: bobs.value[0], y: bobs.value[1] },
    { x: bobs.value[2], y: bobs.value[3] },
  ]);
  const x1 = useDerivedValue(() => bobs.value[0]);
  const y1 = useDerivedValue(() => bobs.value[1]);
  const x2 = useDerivedValue(() => bobs.value[2]);
  const y2 = useDerivedValue(() => bobs.value[3]);
  const buckets = useMemo(() => Array.from({ length: TRAIL_BUCKETS }, (_, i) => i), []);

  return (
    <View
      style={[{ width: PENDULUM_W, height: PENDULUM_H }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ width: PENDULUM_W, height: PENDULUM_H }}>
        <RoundedRect x={0} y={0} width={PENDULUM_W} height={PENDULUM_H} r={18} color={PENDULUM_BACKGROUND} />
        {!reduce
          ? buckets.map((b) => (
              <TrailBucket key={`e${b}`} sim={sim} frame={frame} tip={false} bucket={b} spec={ELBOW_TRAIL} layers={2} />
            ))
          : null}
        {!reduce
          ? buckets.map((b) => (
              <TrailBucket key={`t${b}`} sim={sim} frame={frame} tip bucket={b} spec={TIP_TRAIL} layers={3} />
            ))
          : null}
        <Points points={arm} mode="polygon" color={PENDULUM_ARM} style="stroke" strokeWidth={2} strokeCap="round" strokeJoin="round" />
        <Circle cx={PENDULUM_ORIGIN_X} cy={PENDULUM_ORIGIN_Y} r={5} color={PENDULUM_ARM} />
        <Circle cx={x1} cy={y1} r={BOB_RADIUS + 7} color={ELBOW_TRAIL.head} opacity={0.12} />
        <Circle cx={x1} cy={y1} r={BOB_RADIUS + 3} color={ELBOW_TRAIL.head} opacity={0.25} />
        <Circle cx={x1} cy={y1} r={BOB_RADIUS} color={PENDULUM_BOB} />
        <Circle cx={x2} cy={y2} r={BOB_RADIUS + 7} color={TIP_TRAIL.head} opacity={0.14} />
        <Circle cx={x2} cy={y2} r={BOB_RADIUS + 3} color={TIP_TRAIL.head} opacity={0.3} />
        <Circle cx={x2} cy={y2} r={BOB_RADIUS} color={PENDULUM_BOB} />
      </Canvas>
    </View>
  );
}

export type PendulumPointer = { x: number; y: number; active: number };

export type PendulumConfig = {
  originX: number;
  originY: number;
  pixelsPerMeter: number;
};

export type PendulumPhysics = {
  gravity: number;
  m1: number;
  m2: number;
  l1: number;
  l2: number;
  drag: number;
};

export type PendulumState = {
  th1: number;
  th2: number;
  w1: number;
  w2: number;
  time: number;
  acc: number;
  stepIndex: number;
  grabbed: number;
  hx: number;
  hy: number;
  trail1: Float32Array;
  trail2: Float32Array;
  head: number;
  count: number;
};

export const PENDULUM_DEFAULTS = {
  gravity: 9.81,
  m1: 1,
  m2: 1,
  l1: 1,
  l2: 1,
  drag: 0,
  fixedDt: 1 / 960,
  sampleEvery: 8,
  trailLength: 480,
  grabRate: 20,
  velocitySmoothing: 0.03,
  maxOmega: 32,
  startTh1: 2.1,
  startTh2: 2.6,
};

export type PendulumOptions = typeof PENDULUM_DEFAULTS;

export function createPendulum(opts: PendulumOptions): PendulumState {
  "worklet";
  return {
    th1: opts.startTh1,
    th2: opts.startTh2,
    w1: 0,
    w2: 0,
    time: 0,
    acc: 0,
    stepIndex: 0,
    grabbed: 0,
    hx: 0,
    hy: 0,
    trail1: new Float32Array(opts.trailLength * 2),
    trail2: new Float32Array(opts.trailLength * 2),
    head: 0,
    count: 0,
  };
}

export function restPendulum(s: PendulumState, th1: number, th2: number) {
  "worklet";
  s.th1 = th1;
  s.th2 = th2;
  s.w1 = 0;
  s.w2 = 0;
  s.time = 0;
  s.acc = 0;
  s.stepIndex = 0;
  s.grabbed = 0;
  s.head = 0;
  s.count = 0;
}

export function pendulumAccel(
  th1: number,
  th2: number,
  w1: number,
  w2: number,
  p: PendulumPhysics,
  out: number[],
) {
  "worklet";
  const d = th1 - th2;
  const sd = Math.sin(d);
  const cd = Math.cos(d);
  const den = 2 * p.m1 + p.m2 - p.m2 * Math.cos(2 * d);
  const a1 =
    (-p.gravity * (2 * p.m1 + p.m2) * Math.sin(th1) -
      p.m2 * p.gravity * Math.sin(th1 - 2 * th2) -
      2 * sd * p.m2 * (w2 * w2 * p.l2 + w1 * w1 * p.l1 * cd)) /
    (p.l1 * den);
  const a2 =
    (2 *
      sd *
      (w1 * w1 * p.l1 * (p.m1 + p.m2) +
        p.gravity * (p.m1 + p.m2) * Math.cos(th1) +
        w2 * w2 * p.l2 * p.m2 * cd)) /
    (p.l2 * den);
  out[0] = a1 - p.drag * w1;
  out[1] = a2 - p.drag * w2;
}

export function rk4Step(s: PendulumState, dt: number, p: PendulumPhysics) {
  "worklet";
  const a = [0, 0];
  pendulumAccel(s.th1, s.th2, s.w1, s.w2, p, a);
  const k1t1 = s.w1, k1t2 = s.w2, k1w1 = a[0], k1w2 = a[1];
  const h = dt / 2;
  pendulumAccel(s.th1 + h * k1t1, s.th2 + h * k1t2, s.w1 + h * k1w1, s.w2 + h * k1w2, p, a);
  const k2t1 = s.w1 + h * k1w1, k2t2 = s.w2 + h * k1w2, k2w1 = a[0], k2w2 = a[1];
  pendulumAccel(s.th1 + h * k2t1, s.th2 + h * k2t2, s.w1 + h * k2w1, s.w2 + h * k2w2, p, a);
  const k3t1 = s.w1 + h * k2w1, k3t2 = s.w2 + h * k2w2, k3w1 = a[0], k3w2 = a[1];
  pendulumAccel(s.th1 + dt * k3t1, s.th2 + dt * k3t2, s.w1 + dt * k3w1, s.w2 + dt * k3w2, p, a);
  const k4t1 = s.w1 + dt * k3w1, k4t2 = s.w2 + dt * k3w2, k4w1 = a[0], k4w2 = a[1];
  s.th1 += (dt / 6) * (k1t1 + 2 * k2t1 + 2 * k3t1 + k4t1);
  s.th2 += (dt / 6) * (k1t2 + 2 * k2t2 + 2 * k3t2 + k4t2);
  s.w1 += (dt / 6) * (k1w1 + 2 * k2w1 + 2 * k3w1 + k4w1);
  s.w2 += (dt / 6) * (k1w2 + 2 * k2w2 + 2 * k3w2 + k4w2);
}

export function pendulumEnergy(th1: number, th2: number, w1: number, w2: number, p: PendulumPhysics) {
  "worklet";
  const kinetic =
    0.5 * (p.m1 + p.m2) * p.l1 * p.l1 * w1 * w1 +
    0.5 * p.m2 * p.l2 * p.l2 * w2 * w2 +
    p.m2 * p.l1 * p.l2 * w1 * w2 * Math.cos(th1 - th2);
  const potential = -(p.m1 + p.m2) * p.gravity * p.l1 * Math.cos(th1) - p.m2 * p.gravity * p.l2 * Math.cos(th2);
  return kinetic + potential;
}

export function energyScale(p: PendulumPhysics) {
  "worklet";
  return (p.m1 + p.m2) * p.gravity * p.l1 + p.m2 * p.gravity * p.l2;
}

export function bobPositions(s: PendulumState, cfg: PendulumConfig, p: PendulumPhysics, out: number[]) {
  "worklet";
  const sc = cfg.pixelsPerMeter;
  const x1 = cfg.originX + sc * p.l1 * Math.sin(s.th1);
  const y1 = cfg.originY + sc * p.l1 * Math.cos(s.th1);
  out[0] = x1;
  out[1] = y1;
  out[2] = x1 + sc * p.l2 * Math.sin(s.th2);
  out[3] = y1 + sc * p.l2 * Math.cos(s.th2);
}

function wrapAngle(a: number) {
  "worklet";
  const t = Math.PI * 2;
  return a - t * Math.floor((a + Math.PI) / t);
}

export function trailIndex(s: PendulumState, trailLength: number, age: number) {
  "worklet";
  if (age >= s.count) return -1;
  return (s.head - 1 - age + trailLength) % trailLength;
}

function pushTrail(s: PendulumState, cfg: PendulumConfig, p: PendulumPhysics, trailLength: number, pos: number[]) {
  "worklet";
  bobPositions(s, cfg, p, pos);
  const i = s.head * 2;
  s.trail1[i] = pos[0];
  s.trail1[i + 1] = pos[1];
  s.trail2[i] = pos[2];
  s.trail2[i + 1] = pos[3];
  s.head = (s.head + 1) % trailLength;
  if (s.count < trailLength) s.count += 1;
}

function followHand(s: PendulumState, p: PendulumPhysics, dt: number, opts: PendulumOptions) {
  "worklet";
  const ease = 1 - Math.exp(-opts.grabRate * dt);
  const reachMax = p.l1 + p.l2 - 0.002;
  const reachMin = Math.abs(p.l1 - p.l2) + 0.002;
  let tx = s.hx;
  let ty = s.hy;
  const dist = Math.hypot(tx, ty);
  if (dist > reachMax || dist < reachMin) {
    const f = (dist > reachMax ? reachMax : reachMin) / (dist || 1);
    tx = dist === 0 ? 0 : tx * f;
    ty = dist === 0 ? reachMin : ty * f;
  }
  const bx = p.l1 * Math.sin(s.th1) + p.l2 * Math.sin(s.th2);
  const by = p.l1 * Math.cos(s.th1) + p.l2 * Math.cos(s.th2);
  const nx = bx + (tx - bx) * ease;
  const ny = by + (ty - by) * ease;
  const d = Math.min(reachMax, Math.max(reachMin, Math.hypot(nx, ny)));
  const phi = Math.atan2(nx, ny);
  const cosA = Math.max(-1, Math.min(1, (p.l1 * p.l1 + d * d - p.l2 * p.l2) / (2 * p.l1 * d)));
  const alpha = Math.acos(cosA);
  const c1 = phi + alpha;
  const c2 = phi - alpha;
  const pick = Math.abs(wrapAngle(c1 - s.th1)) <= Math.abs(wrapAngle(c2 - s.th1)) ? c1 : c2;
  const th1 = s.th1 + wrapAngle(pick - s.th1);
  const ex = nx * (d / (Math.hypot(nx, ny) || 1)) - p.l1 * Math.sin(th1);
  const ey = ny * (d / (Math.hypot(nx, ny) || 1)) - p.l1 * Math.cos(th1);
  const th2 = s.th2 + wrapAngle(Math.atan2(ex, ey) - s.th2);
  const blend = 1 - Math.exp(-dt / opts.velocitySmoothing);
  s.w1 += ((th1 - s.th1) / dt - s.w1) * blend;
  s.w2 += ((th2 - s.th2) / dt - s.w2) * blend;
  s.th1 = th1;
  s.th2 = th2;
}

export function stepPendulumFixed(
  s: PendulumState,
  cfg: PendulumConfig,
  dtFrame: number,
  pointer: PendulumPointer,
  opts: PendulumOptions,
) {
  "worklet";
  if (pointer.active) {
    s.hx = (pointer.x - cfg.originX) / cfg.pixelsPerMeter;
    s.hy = (pointer.y - cfg.originY) / cfg.pixelsPerMeter;
    if (!s.grabbed) {
      s.grabbed = 1;
      s.w1 = 0;
      s.w2 = 0;
    }
  } else if (s.grabbed) {
    s.grabbed = 0;
    s.w1 = Math.max(-opts.maxOmega, Math.min(opts.maxOmega, s.w1));
    s.w2 = Math.max(-opts.maxOmega, Math.min(opts.maxOmega, s.w2));
  }
  s.acc += Math.min(dtFrame, 0.05);
  const dt = opts.fixedDt;
  const pos = [0, 0, 0, 0];
  while (s.acc >= dt) {
    if (s.grabbed) followHand(s, opts, dt, opts);
    else rk4Step(s, dt, opts);
    s.acc -= dt;
    s.time += dt;
    s.stepIndex += 1;
    if (s.stepIndex % opts.sampleEvery === 0) pushTrail(s, cfg, opts, opts.trailLength, pos);
  }
}

export const PENDULUM_W = 320;
export const PENDULUM_H = 340;
export const PENDULUM_ORIGIN_X = 160;
export const PENDULUM_ORIGIN_Y = 170;
export const PENDULUM_PX_PER_M = 70;
export const PENDULUM_BACKGROUND = "#0b1020";
export const PENDULUM_ARM = "#c9d1ee";
export const PENDULUM_BOB = "#f6f1e4";
export const BOB_RADIUS = 10;
export const TRAIL_BUCKETS = 12;

export const TRAIL_LAYERS = [
  { width: 9, alpha: 0.14 },
  { width: 4.5, alpha: 0.32 },
  { width: 1.8, alpha: 0.95 },
] as const;

export type TrailSpec = { head: string; tail: string; strength: number };

export const TIP_TRAIL: TrailSpec = { head: "#ffd27a", tail: "#ff4f8b", strength: 1 };
export const ELBOW_TRAIL: TrailSpec = { head: "#8ce8ff", tail: "#5a63ff", strength: 0.7 };

function channel(hex: string, at: number) {
  return parseInt(hex.slice(at, at + 2), 16);
}

export function trailStyle(spec: TrailSpec, bucket: number, buckets: number) {
  const t = bucket / Math.max(1, buckets - 1);
  const mix = (at: number) => Math.round(channel(spec.head, at) + (channel(spec.tail, at) - channel(spec.head, at)) * t);
  const fade = Math.pow(1 - bucket / buckets, 1.5) * spec.strength;
  return { color: `rgb(${mix(1)},${mix(3)},${mix(5)})`, alpha: fade };
}

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { ChaosPendulum } from "./ChaosPendulum";

export default function Example({ onFeedback }: { onFeedback?: (event: "grab" | "release") => void }) {
  const [slow, setSlow] = useState(false),
    [reduce, setReduce] = useState(false);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <ChaosPendulum slowMotion={slow} reducedMotion={reduce} onFeedback={onFeedback} />
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f", fontFamily: "Geist-Regular" }}>Grab the pendulum and fling it. The trails fade over four seconds.</Text>
    </View>
  );
}
